import {orderedProductMedia,validProductVideo,HOME_CATEGORIES} from './product-media.js';
import { readMarketplace, saveMarketplace, auditMarketplace, sellerContext, sealMetrics, sealSVG, validateEstablishment } from './marketplace-settings.js';
import { readDemoOrders, saveDemoOrders } from './order-storage.js';
import { advanceDemoSuborder, statusLabel, orderEvent } from './order-model.js';
const adminEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const adminField=(label,name,value='',type='text',extra='')=>`<label class="field-label">${label}<input class="panel-input" name="${name}" value="${adminEsc(value)}" type="${type}" ${extra}></label>`;
const adminSelect=(label,name,options,value)=>`<label class="field-label">${label}<select class="panel-input" name="${name}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;
const unitFields=(s={})=>adminField('Razão social da unidade','company',s.company||'','text','required')+adminField('Rua / avenida da unidade','street',s.street||'','text','required')+adminField('Número','number',s.number||'','text','required')+adminField('Bairro','neighborhood',s.neighborhood||'','text','required')+adminField('UF','state',s.state||'PR','text','required pattern="[A-Z]{2}"')+adminField('Complemento','complement',s.complement||'');
const adminSave='<label class="field-label">Motivo da alteração<input class="panel-input" name="reason" required maxlength="200" value="Atualização de configuração"></label><button class="btn">Salvar e aplicar no protótipo</button>';
const adminCard=(title,body)=>`<section class="portal-panel"><h2>${title}</h2>${body}</section>`;
export function adminContent(page,role='admin'){
  const c=readMarketplace(),own=c.stores.find(s=>s.id===sellerContext())||c.stores[0],isAdmin=role==='admin';let body='';
  if(page==='inicio'&&isAdmin)body=adminCard('Tem Logo Ali · Administração',`<p>Domínio adquirido: <strong>${c.domain}</strong></p><div class="portal-cards"><article class="portal-card"><h3>${c.stores.length} lojas</h3><a href="#admin/sellers">Gerenciar vendedores</a></article><article class="portal-card"><h3>${readDemoOrders().length} compras</h3><a href="#admin/pedidos">Acompanhar pedidos</a></article><article class="portal-card"><h3>${c.modules.length} módulos personalizados</h3><a href="#admin/vitrines">Compor a home</a></article></div><p>As configurações e intervenções são locais. O ambiente ainda não possui autenticação administrativa real, cobrança ou envio de mensagens.</p>`);
  if(page==='sellers')body=c.stores.map(s=>adminCard(s.name,`<form data-admin-form="store" data-store="${s.id}"><div class="form-two">${adminField('Nome da loja','name',s.name,'text','required')}${adminField('CNPJ (somente demonstração)','cnpj',s.cnpj||'','text','pattern="[0-9]{14}" title="14 dígitos"')}${adminField('Cidade','city',s.city,'text','required')}${adminField('CEP da loja física','cep',s.cep,'text','required pattern="[0-9]{8}"')}${unitFields(s)}${adminSelect('Situação comercial','status',[['pending','Em análise'],['active','Aprovada'],['suspended','Suspensa']],s.status)}</div>${adminSave}</form><button class="btn secondary" data-manage-store="${s.id}">Administrar esta loja</button>`)).join('')+adminCard('Cadastrar loja ou filial',`<p>Cada estabelecimento precisa de cadastro e aprovação próprios. A retirada fica restrita à cidade do CEP físico desta unidade, mesmo que a marca opere em outras cidades.</p><form data-admin-form="new-store">${unitFields()}${adminField('Nome','name','','text','required')}${adminField('CNPJ','cnpj','','text','required pattern="[0-9]{14}"')}${adminField('Cidade','city','','text','required')}${adminField('CEP físico','cep','','text','required pattern="[0-9]{8}"')}${adminSave}</form>`);
  if(page==='logistica')body=(isAdmin?c.stores:[own]).map(s=>adminCard('Origem e logística · '+adminEsc(s.name),`<form data-admin-form="logistics" data-store="${s.id}"><div class="form-two">${adminField('CEP físico de saída','cep',s.cep,'text','required pattern="[0-9]{8}"')}${adminField('Faixa atendida: CEP inicial','from',s.from,'text','required pattern="[0-9]{8}"')}${adminField('Faixa atendida: CEP final','to',s.to,'text','required pattern="[0-9]{8}"')}${adminField('Tarifa de entrega por km (R$)','rate',s.rate/100,'number','required min="0" step="0.01"')}${adminField('Entrega: distância máxima pelas ruas (km)','maxKm',s.maxKm,'number','required min="0.01" step="0.01"')}${adminField('Trajeto de teste por CEP (km) · simulação','routeKm',s.routeKm??3.4,'number','required min="0.01" step="0.01"')}${adminField('Horário de corte (somente seller/admin)','cutoff',s.cutoff,'time','required')}</div><p>A retirada atende apenas compradores na faixa de CEP da cidade desta unidade. Para outra cidade, cadastre e aprove outra loja ou filial com seus próprios dados fiscais e endereço. A faixa de entrega não amplia a retirada. Não há limite de distância para retirada. Alterar o corte vale somente para novos pedidos; os prazos já confirmados são preservados.</p>${adminSave}</form>`)).join('');
  if(page==='regras')body=adminCard('Adicionar região',`<form data-admin-form="region">${adminField('Cidade / região','name','','text','required')}${adminField('CEP inicial','from','','text','required pattern="[0-9]{8}"')}${adminField('CEP final','to','','text','required pattern="[0-9]{8}"')}${adminSave}</form>`)+adminCard('Regiões e regras globais',`<form data-admin-form="rules">${adminField('Comissão uniforme sobre produtos (%) · 0 = ainda não definida','commission',c.commission,'number','required min="0" max="100" step="0.01"')}${adminField('Tempo por km de trajeto (minutos) · parâmetro demonstrativo','minutesPerKm',c.minutesPerKm,'number','required min="1" max="120"')}<p>Faixas de CEP abaixo são exemplos de teste e precisam de validação operacional antes da publicação.</p>${c.regions.map((r,i)=>`<fieldset><legend>${adminEsc(r.name)}</legend>${adminField('Cidade / região','region-name-'+i,r.name,'text','required')}${adminField('CEP inicial','region-from-'+i,r.from,'text','required pattern="[0-9]{8}"')}${adminField('CEP final','region-to-'+i,r.to,'text','required pattern="[0-9]{8}"')}</fieldset>`).join('')}${adminSave}</form><p>Concessão Indicada: 100 pedidos realizados em um dia. Manutenção: média diária de 100 nos últimos 6 meses. Oficial: três documentos aprovados, sem exigência de volume. Aprovação de pedidos apenas por intervenção.</p>`);
  if(page==='financeiro')body=adminCard('Resumo de pedidos · sem conciliação bancária',readDemoOrders().flatMap(o=>o.suborders.filter(s=>isAdmin||s.store===own.id).map(s=>'<article class="module-row"><div><b>'+adminEsc(s.storeName)+' · '+adminEsc(s.id)+'</b><p>Pagamento: '+adminEsc(o.payment)+' · Produtos: R$ '+(s.subtotal/100).toFixed(2)+' · Frete: R$ '+(s.freight/100).toFixed(2)+' · Desconto: R$ '+((s.discount||0)/100).toFixed(2)+'</p><p>Comissão sobre produtos: R$ '+((s.commission||0)/100).toFixed(2)+' · Total do pedido: R$ '+(s.total/100).toFixed(2)+'</p><small>Taxas do provedor e repasses ainda não integrados.</small></div></article>')).join('')||'<p>Nenhum pedido registrado.</p>');
  if(page==='financeiro'){
   const paid=readDemoOrders().filter(o=>o.payment==='paid').flatMap(o=>o.suborders.filter(s=>(isAdmin||s.store===own.id)&&s.status!=='cancelled'));
   const value=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100),sum=f=>paid.reduce((a,s)=>a+f(s),0),net=s=>s.total-(s.commission||0)-(s.paymentFee||0);
   body=adminCard('Financeiro da loja · demonstração', '<p>Os pedidos EXEMPLO são fictícios. Neles, simulamos comissão de 10% sobre produtos e taxa de pagamento de 2% sobre o total. Estes percentuais não alteram as regras comerciais do marketplace. Concluído representa saldo disponível na simulação; não há repasse bancário.</p><div class="portal-cards">'+[['Vendas pagas',sum(s=>s.total)],['Comissões',sum(s=>s.commission||0)],['Taxas de pagamento',sum(s=>s.paymentFee||0)],['Líquido simulado',sum(net)],['Disponível simulado',sum(s=>s.status==='completed'?net(s):0)],['A liberar simulado',sum(s=>s.status!=='completed'?net(s):0)]].map(([label,n])=>'<article class="portal-card"><small>'+label+'</small><h3>'+value(n)+'</h3></article>').join('')+'</div>')+body;
  }
  if(page==='pagamentos')body=adminCard('Pagamento e split',`<form data-admin-form="payments">${adminSelect('Provedor pretendido','provider',[['pending','A definir'],['mercadopago','Mercado Pago'],['pagarme','Pagar.me'],['other','Outro']],c.provider)}<label><input name="pix" type="checkbox" ${c.pix?'checked':''}> Pix habilitado</label> <label><input name="card" type="checkbox" ${c.card?'checked':''}> Cartão habilitado</label><p>Sem conexão com provedores. Não insira chaves secretas no frontend. Comissão somente sobre produtos; frete destinado à loja. Taxa do meio de pagamento descontada do seller por pedido, conforme contrato ainda a definir.</p>${adminSave}</form>`);
  if(page==='cupons')body=adminCard('Cupons e frete grátis',`<form data-admin-form="coupon"><div class="form-two">${adminField('Código (letras e números)','code','','text','required pattern="[A-Za-z0-9]{3,20}"')}${adminField('Desconto sobre produtos (%)','percent',10,'number','required min="1" max="100"')}${adminField('Mínimo em produtos por loja (R$)','minimum',0,'number','required min="0" step="0.01"')}</div><p>Regra demonstrativa global, desconto custeado pelo seller. Aplica-se separadamente ao subtotal de cada loja.</p>${adminSave}</form>${c.coupons.map(x=>`<p>${adminEsc(x.code)} · ${x.percent}% · ${x.active?'Ativo':'Desativado'} <button class="text-link" data-toggle-coupon="${adminEsc(x.code)}">Alternar situação</button></p>`).join('')}<form data-admin-form="freight">${adminField('Frete grátis a partir de R$ em produtos por loja (0 = desativado)','minimum',c.freeShippingMinimum/100,'number','required min="0" step="0.01"')}<p>Subsídio demonstrativo custeado pela loja. Não altera a cobertura geográfica.</p>${adminSave}</form>`);
  if(page==='vitrines'||page==='aparencia'){const scope=isAdmin?'global':String(own.id),modules=isAdmin?c.modules:(c.storeModules[own.id]||[]);body=!isAdmin&&own.seal==='none'?adminCard('Vitrine da loja','Disponível para lojas Indicadas e Oficiais.'):adminCard(isAdmin?'Composição modular da home':'Vitrine da loja · '+adminEsc(own.name),`<p>Os módulos são publicados na ordem abaixo. Escolha quantidade e ordem dos produtos, carrossel ou grade. Adicione banners, mosaicos e categorias. Apenas produtos da própria loja podem compor seus módulos. Ao publicar o primeiro módulo, a composição personalizada substitui os módulos demonstrativos.</p>${modules.map((m,i)=>`<div class="module-row"><b>${i+1}. ${adminEsc(m.title)}</b><span>${m.type} · ${m.count||1} item(s)</span><button data-module-up="${i}" data-scope="${scope}" ${i===0?'disabled':''}>↑</button><button data-module-down="${i}" data-scope="${scope}" ${i===modules.length-1?'disabled':''}>↓</button><button data-module-remove="${i}" data-scope="${scope}">Remover</button></div>`).join('')}<form data-admin-form="module" data-scope="${scope}">${adminSelect('Tipo de módulo','type',[['showcase','Produtos em carrossel'],['grid','Produtos em grade'],['categories','Categorias da loja'],['banner','Banner horizontal'],['mosaic','Mosaico de banners'],['video','Vídeo']], 'showcase')}${adminField('Título','title','','text','required maxlength="90"')}${adminField('Quantidade de produtos','count',10,'number','required min="1" max="50"')}${adminField('Produtos na ordem de exibição (códigos separados por vírgula; vazio = catálogo da área)','ids','','text','pattern="[0-9, ]*"')}${adminField('Imagem do banner (HTTPS; opcional)','image','','url')}${adminField('Vídeo MP4/WebM (HTTPS; vazio usa vídeo dos produtos selecionados)','videoUrl','','url')}<label><input type="checkbox" name="autoplay" checked> Reproduzir vídeo automaticamente sem som</label>${adminField('Imagens do mosaico (URLs HTTPS separadas por vírgula; opcional)','images','','text')}${adminField('Destino interno do banner','target','#/busca','text','required pattern="#(/busca.*|/produto/[0-9]+|/loja/[0-9]+.*)"')}<p>No mosaico, os IDs definem os produtos de cada banner. Sem imagem própria, usa as imagens do catálogo.</p>${adminSave}</form>`);}
  if(page==='vitrines'&&isAdmin){body+=adminCard('Banners e vídeos das categorias',`<p>Composição independente por categoria. Defina topo, entre produtos ou final da listagem. Os conteúdos respeitam os produtos visíveis para o CEP do comprador.</p>${Object.entries(c.categoryModules||{}).map(([category,modules])=>`<h3>${adminEsc(category)}</h3>${modules.map((m,i)=>`<div class="module-row"><b>${adminEsc(m.title)}</b><span>${m.type} · ${m.placement} ${m.placement==='grid'?'· antes do produto '+m.position:''}</span><button data-module-up="${i}" data-scope="category:${adminEsc(category)}" ${i===0?'disabled':''}>↑</button><button data-module-down="${i}" data-scope="category:${adminEsc(category)}" ${i===modules.length-1?'disabled':''}>↓</button><button data-module-remove="${i}" data-scope="category:${adminEsc(category)}">Remover</button></div>`).join('')}`).join('')}<form data-admin-form="module" data-scope="category">${adminSelect('Categoria','category',HOME_CATEGORIES.map(([name])=>[name,name]),HOME_CATEGORIES[0][0])}${adminSelect('Mídia','type',[['banner','Banner'],['video','Vídeo']],'banner')}${adminField('Título','title','','text','required maxlength="90"')}${adminSelect('Posicionamento','placement',[['top','Topo da categoria'],['grid','Entre os produtos'],['bottom','Após os produtos']],'top')}${adminField('Inserir antes do produto número (quando entre produtos)','position',3,'number','min="1" max="100" required')}${adminField('Produtos vinculados (IDs; vazio usa a categoria)','ids','','text','pattern="[0-9, ]*"')}${adminField('Imagem / capa do vídeo (HTTPS; opcional)','image','','url')}${adminField('Vídeo MP4/WebM (HTTPS; vazio usa vídeo de produto vinculado)','videoUrl','','url')}<label><input name="autoplay" type="checkbox" checked> Reproduzir automaticamente sem som</label>${adminField('Destino interno','target','#/busca','text','required pattern="#(/busca.*|/produto/[0-9]+|/loja/[0-9]+.*)"')}${adminSave}</form>`);}
  if(page==='classificacao')body=(isAdmin?c.stores:[own]).map(s=>{const m=sealMetrics(readDemoOrders(),s.id);return adminCard('Classificação · '+adminEsc(s.name),`${s.seal!=='none'?`<div class="seal-preview">${sealSVG(s.seal)}</div>`:''}<p>Maior volume diário registrado: ${m.peak}. Média nos últimos ${m.days} dias: ${m.average.toFixed(2)} pedidos/dia. Pedidos realizados contam sem confirmação de pagamento.</p><p>Primeira concessão: 100 pedidos em um dia. Revisão Indicada: média diária de 100 nos últimos 6 meses. Oficial não exige vendas. Lojas e validações iniciais são fictícias.</p>${isAdmin?`<form data-admin-form="seal" data-store="${s.id}">${['Registro de Marca','Cartão CNPJ','Contrato social'].map((d,i)=>`<label class="document-check"><input type="checkbox" name="doc-${i}" ${s.documents[i]?'checked':''}>${d} aprovado</label>`).join('')}${adminSelect('Classificação','seal',[['none','Sem selo'],['indicated','Loja Indicada'],['official','Loja Oficial']],s.seal)}<label><input name="review" type="checkbox"> Revisão semestral (usar média diária)</label>${adminSave}</form>`:'<p>Documentos devem ser recebidos em canal privado na integração de produção. Não envie documentos reais neste protótipo.</p>'}`)}).join('');
  if(page==='notificacoes')body=adminCard('Notificações de pedidos',`<form data-admin-form="notifications">${adminField('Provedor de e-mail (nome, sem credenciais)','emailProvider',c.notifications.emailProvider)}${adminField('Provedor WhatsApp (nome, sem credenciais)','whatsappProvider',c.notifications.whatsappProvider)}${adminField('Modelo de e-mail','email',c.notifications.email,'text','required')}${adminField('Modelo WhatsApp','whatsapp',c.notifications.whatsapp,'text','required')}<p>Variáveis: {pedido} e {status}. Cada evento gera uma mensagem em cada canal. A entrega digital inclui referência ao item e à área de downloads. Nenhuma mensagem é enviada por este protótipo.</p>${adminSave}</form>`)+adminCard('Fila de saída · aguardando integração',readDemoOrders().flatMap(o=>(o.notifications||[]).map(n=>`<details><summary>${adminEsc(n.subject)} · ${n.channel} · ${adminEsc(n.subId)}</summary><p>Estado: aguardando provedor • Destinatário: ${adminEsc(n.recipient||'não informado')}</p><p>${adminEsc(n.body)}</p>${n.downloads.map(d=>`<p>Item digital: ${adminEsc(d.name)} — ${adminEsc(d.access)}</p>`).join('')}<small>${adminEsc(n.id)}</small></details>`)).join('')||'<p>Nenhuma notificação gerada.</p>');
  if(page==='aprovacao'){let drafts=[];try{drafts=JSON.parse(localStorage.getItem('marketplace.product-drafts.v1')||'[]')}catch{}body=adminCard('Revisão de produtos',drafts.map(d=>`<article class="module-row"><div><b>${adminEsc(d.name)}</b><p>${adminEsc(d.type)} · ${adminEsc(d.status)} · Loja ${d.store}</p><details><summary>Revisar conteúdo e ordem das mídias</summary><div class="review-media">${orderedProductMedia(d).map((m,i)=>`<figure><figcaption>${i+1}. ${m.type==='video'?'Vídeo':'Foto'}${i===0?' · Capa':''}</figcaption>${m.type==='video'?`<video controls preload="metadata" src="${adminEsc(m.src)}"></video>`:`<img src="${adminEsc(m.src)}" alt="${adminEsc(d.name)}">`}</figure>`).join('')}</div><pre>${adminEsc(JSON.stringify(d,(key,value)=>typeof value==='string'&&value.startsWith('data:')?'[Arquivo local incorporado]':value,2))}</pre></details></div><button data-moderate="approved" data-draft="${d.id}">Aprovar</button><button data-moderate="rejected" data-draft="${d.id}">Rejeitar</button></article>`).join('')||'<p>Sem produtos enviados. Cadastre pela Central de Vendedores.</p>')+'<p>As decisões ficam registradas localmente. A publicação no catálogo de produção exige backend; preço e estoque não são sobrescritos pela revisão.</p>';}
  if(page==='auditoria')body=adminCard('Auditoria local',c.audit.slice().reverse().map(a=>`<article class="module-row"><div><b>${adminEsc(a.action)}</b><p>${adminEsc(a.actor)} · ${new Date(a.at).toLocaleString('pt-BR')}</p><p>${adminEsc(a.reason)}</p></div></article>`).join('')||'<p>Nenhuma alteração registrada.</p>');
  if(!body)return null;return `<div id="admin-workspace">${body}<p id="admin-feedback" role="status"></p></div>`;
}
export function mountAdminContent(refresh,role='admin'){
  const root=document.querySelector('#admin-workspace');if(!root)return;const actor=role==='admin'?'Administrador':`Operador da loja ${sellerContext()}`;
  const fail=e=>root.querySelector('#admin-feedback').textContent=e.message;
  root.onsubmit=e=>{const f=e.target.closest('[data-admin-form]');if(!f)return;e.preventDefault();try{const c=readMarketplace(),d=Object.fromEntries(new FormData(f)),kind=f.dataset.adminForm,s=c.stores.find(s=>s.id===Number(f.dataset.store));
    if([d.name,d.city,d.title].some(v=>v&&/[<>]/.test(v)))throw Error('Use texto sem marcação HTML.');if(kind==='region'){if(d.from>d.to||c.regions.some(r=>r.from<=d.to&&d.from<=r.to))throw Error('Faixa invertida ou sobreposta.');c.regions.push({name:d.name,from:d.from,to:d.to});}
    if(kind==='store'){validateEstablishment(d,c);if(d.city!==s.city)throw Error('Para outra cidade, cadastre uma nova loja ou filial.');Object.assign(s,{name:d.name,cnpj:d.cnpj,city:d.city,cep:d.cep,status:d.status,company:d.company,street:d.street,number:d.number,neighborhood:d.neighborhood,state:d.state,complement:d.complement});}
    if(kind==='new-store'){validateEstablishment(d,c);if(c.stores.some(s=>s.cnpj===d.cnpj))throw Error('CNPJ já cadastrado.');c.stores.push({id:Math.max(...c.stores.map(s=>s.id))+1,name:d.name,cnpj:d.cnpj,city:d.city,cep:d.cep,company:d.company,street:d.street,number:d.number,neighborhood:d.neighborhood,state:d.state,complement:d.complement,from:d.cep,to:d.cep,rate:250,maxKm:10,cutoff:'15:00',status:'pending',seal:'none',documents:[false,false,false]});}
    if(kind==='logistics'){validateEstablishment({...s,cep:d.cep},c);if(d.cep!==s.cep)throw Error('Altere o endereço físico no cadastro administrativo da unidade, com os dados fiscais correspondentes. Para outra cidade, cadastre uma filial.');if(d.from>d.to)throw Error('Faixa de CEP invertida.');Object.assign(s,{cep:d.cep,from:d.from,to:d.to,rate:Math.round(Number(d.rate)*100),maxKm:Number(d.maxKm),routeKm:Number(d.routeKm),cutoff:d.cutoff});}
    if(kind==='rules'){c.commission=Number(d.commission);c.minutesPerKm=Number(d.minutesPerKm);c.regions=c.regions.map((r,i)=>({name:d['region-name-'+i],from:d['region-from-'+i],to:d['region-to-'+i]}));if(c.regions.some(r=>r.from>r.to))throw Error('Faixa de CEP invertida.');if(c.regions.some((r,i)=>c.regions.some((x,j)=>i!==j&&r.from<=x.to&&x.from<=r.to)))throw Error('Faixas de regiões não podem se sobrepor.');}
    if(kind==='payments'){if(!d.pix&&!d.card)throw Error('Habilite ao menos uma forma de pagamento.');Object.assign(c,{provider:d.provider,pix:!!d.pix,card:!!d.card});}
    if(kind==='coupon'){const code=d.code.toUpperCase();c.coupons=c.coupons.filter(x=>x.code!==code).concat({code,percent:Number(d.percent),minimum:Math.round(Number(d.minimum)*100),active:true});}
    if(kind==='freight')c.freeShippingMinimum=Math.round(Number(d.minimum)*100);
    if(kind==='module'){if(role!=='admin'&&(f.dataset.scope!==String(sellerContext())||!['official','indicated'].includes(c.stores.find(s=>s.id===sellerContext())?.seal)))throw Error('Personalização disponível apenas para sua loja Indicada ou Oficial.');if(d.images&&d.images.split(',').some(url=>!/^https:\/\//.test(url.trim())))throw Error('Use imagens HTTPS.');if(f.dataset.scope==='category'&&!HOME_CATEGORIES.some(([name])=>name===d.category))throw Error('Categoria inválida.');if(d.type==='video'&&d.videoUrl&&!validProductVideo(d.videoUrl))throw Error('Use um vídeo MP4 ou WebM em HTTPS.');if(d.placement==='grid'&&(!Number.isInteger(Number(d.position))||Number(d.position)<1))throw Error('Informe uma posição válida.');const list=f.dataset.scope==='category'?((c.categoryModules||={})[d.category]||=[]):f.dataset.scope==='global'?c.modules:(c.storeModules[f.dataset.scope]||=[]);if(d.image&&!/^https:\/\//.test(d.image))throw Error('Use imagem HTTPS.');list.push({type:d.type,title:d.title,videoUrl:d.videoUrl,autoplay:!!d.autoplay,placement:d.placement||'top',position:Number(d.position)||1,count:Number(d.count)||10,ids:d.ids.split(',').map(x=>x.trim()).filter(Boolean).map(Number),image:d.image,images:(d.images||'').split(',').map(x=>x.trim()).filter(Boolean),target:d.target});}
    if(kind==='seal'){const docs=[0,1,2].map(i=>!!d['doc-'+i]),metrics=sealMetrics(readDemoOrders(),s.id);if(d.seal==='official'&&!docs.every(Boolean))throw Error('Aprove os três documentos para conceder Oficial.');if(d.seal==='indicated'&&(d.review?metrics.average:metrics.peak)<100)throw Error('Volume registrado não atende ao critério de 100 pedidos.');Object.assign(s,{seal:d.seal,documents:docs,reviewedAt:new Date().toISOString()});}
    if(kind==='notifications')c.notifications={emailProvider:d.emailProvider,whatsappProvider:d.whatsappProvider,email:d.email,whatsapp:d.whatsapp};
    saveMarketplace(c,`${kind}${s?' · '+s.name:''}`,d.reason,actor);refresh();document.querySelector('#admin-feedback').textContent='Configuração salva e aplicada neste navegador.';
  }catch(err){fail(err)}};
  root.onclick=e=>{const b=e.target.closest('button');if(!b||(b.type==='submit'&&b.closest('form')))return;try{const c=readMarketplace();if(b.dataset.manageStore!==undefined){const reason=prompt('Motivo para administrar esta loja:');if(!reason)return;auditMarketplace('Acesso à loja '+b.dataset.manageStore,reason);sessionStorage.setItem('temlogoali.seller-context',b.dataset.manageStore);sessionStorage.setItem('marketplace.seller.demo-session','active');location.hash='seller/logistica';return;}
    if(b.dataset.toggleCoupon){c.coupons.find(x=>x.code===b.dataset.toggleCoupon).active^=true;saveMarketplace(c,'Alternar cupom '+b.dataset.toggleCoupon);refresh();}
    for(const key of ['moduleUp','moduleDown','moduleRemove'])if(b.dataset[key]!==undefined){if(role!=='admin'&&(b.dataset.scope!==String(sellerContext())||!['official','indicated'].includes(c.stores.find(s=>s.id===sellerContext())?.seal)))throw Error('Edição não permitida para esta loja.');const list=b.dataset.scope.startsWith('category:')?c.categoryModules?.[b.dataset.scope.slice(9)]:b.dataset.scope==='global'?c.modules:c.storeModules[b.dataset.scope],i=Number(b.dataset[key]);if(!list||!Number.isInteger(i)||i<0||i>=list.length)throw Error('Módulo não encontrado.');if(key==='moduleRemove')list.splice(i,1);else{const j=i+(key==='moduleUp'?-1:1);if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];}saveMarketplace(c,'Alterar composição de módulos');refresh();}
    if(b.dataset.moderate){const reason=prompt('Motivo da decisão editorial:');if(!reason)return;const drafts=JSON.parse(localStorage.getItem('marketplace.product-drafts.v1')||'[]'),d=drafts.find(x=>String(x.id)===b.dataset.draft);d.status=b.dataset.moderate;d.reviewReason=reason;localStorage.setItem('marketplace.product-drafts.v1',JSON.stringify(drafts));auditMarketplace('Produto '+d.name+' · '+d.status,reason);refresh();}
  }catch(err){fail(err)}};
}

